def cancelingStampsTotalReceipt(readings):
    a=readings
    out=[]
    for x in a:
        if out and out[-1]==x: out.pop()
        else: out.append(x)
    return sum(out)


java
class Solution {
  public int cancelingStampsTotalReceipt(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a){if(!out.isEmpty()&&out.get(out.size()-1)==x)out.remove(out.size()-1);else out.add(x);}}
    int answer=0;for(int x:out)answer+=x;return answer;
  }
}
